        for(int i = 1; i + len - 1 <= n; ++i) {
            int j = i + len - 1;
            dp[i][j] = INF;
            // choose k as the vertex forming triangle (i, k, j) where i < k < j
            for(int k = i + 1; k <= j - 1; ++k) {
                long long cost = dp[i][k] + dp[k][j] + 1LL * i * k * j;
