#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // DP table: dp[i][j] = min weight for polygon from i to j (inclusive)
    // We use 1-based indexing for vertices 1..n
    // To avoid modulo, we duplicate the array or use a 2D array of size n x n
    // Since n <= 500, O(n^3) is feasible (500^3 = 125e6, might be tight but acceptable in C++ with optimizations)
    // We'll use 1-based indexing for vertices 1..n
    // But for interval DP on a circle, we can fix vertex 1 and consider intervals [i, j] with j-i+1 >= 3
    // Actually, the polygon is convex and vertices are labeled 1..n in order.
    // Standard triangulation DP: dp[i][j] = min_{i<k<j} dp[i][k] + dp[k][j] + i * k * j
    // where vertices are numbered from 1 to n, and we assume the polygon edges are (i,i+1) and (n,1).
    // However, the DP works if we consider intervals of consecutive vertices.
    // Since it's a circle, we can duplicate the array or just do DP on [1..n] with the understanding that
    // the base polygon is the entire polygon. The standard way: dp[i][j] for 1 <= i < j <= n,
    // where the subpolygon consists of vertices i, i+1, ..., j (in order along the boundary).
    // The edges of this subpolygon are the chain from i to j and the chord (i,j) (which is a diagonal of the original polygon).
    // The recurrence: for segment [i, j] with length >= 3, we pick a vertex k between i and j to form triangle (i, k, j).
    // Then the polygon is split into [i, k] and [k, j].
    // dp[i][j] = min_{k=i+1}^{j-1} (dp[i][k] + dp[k][j] + i * k * j).
    // Base case: dp[i][i+1] = 0 (line segment, no triangles), dp[i][i+2] = i*(i+1)*(i+2) (single triangle).
    // We need to compute dp[1][n].
    // However, note that in the polygon [1..n], the edge (1,n) is a side of the original polygon, not a diagonal.
    // So the subpolygons we consider always have the chord (i,j) as one edge.
    // This recurrence correctly considers all triangulations.
    // Since n <= 500, O(n^3) is 125 million operations, which is acceptable in C++ (usually < 1 second).
    // We'll use 2D array of long long.

    const long long INF = 1e18;
    vector<vector<long long>> dp(n+1, vector<long long>(n+1, 0));

    // Initialize for length 2 (i.e., j = i+1): dp[i][i+1] = 0
    // Actually our dp is 0 by default, which is correct for adjacent vertices.
    // For length 3: dp[i][i+2] = i*(i+1)*(i+2)
    for (int i = 1; i + 2 <= n; ++i) {
        dp[i][i+2] = (long long)i * (i+1) * (i+2);
    }

    // We need to compute for increasing lengths L from 4 to n.
    // Length L = number of vertices in the chain = j - i + 1.
    for (int len = 4; len <= n; ++len) {
        for (int i = 1; i + len - 1 <= n; ++i) {
            int j = i + len - 1;
            long long best = INF;
            for (int k = i + 1; k < j; ++k) {
                long long cost = dp[i][k] + dp[k][j] + (long long)i * k * j;
                if (cost < best) best = cost;
            }
            dp[i][j] = best;
        }
    }

    cout << dp[1][n] << "\n";
    return 0;
}
