#include <iostream>
#include <vector>
#include <climits>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    if (n == 3) {
        cout << 6 << '\n';
        return 0;
    }

    // dp[i][j] = minimum weight of triangulation for polygon from vertex i to j
    // Vertices are 1-indexed: i, i+1, ..., j
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));

    // For polygons with 2 or fewer vertices (edges), weight is 0
    for (int i = 1; i <= n; ++i) {
        dp[i][i] = 0;
        if (i + 1 <= n) dp[i][i+1] = 0;
        if (i + 2 <= n) dp[i][i+2] = (long long)i * (i+1) * (i+2);
    }
    // Handle wrap-around for triangle (n-1, n, 1) etc., but we don't need them as we build up from length 3 to n.
    // The main polygon is from 1 to n.

    // Length of polygon chain (number of vertices)
    // len = 3 means 3 vertices (triangle), len = 4 means 4 vertices (quadrilateral), etc.
    for (int len = 4; len <= n; ++len) {
        for (int i = 1; i + len - 1 <= n; ++i) {
            int j = i + len - 1;
            long long min_val = LLONG_MAX;
            // k is the vertex between i and j to form triangle (i, k, j)
            for (int k = i + 1; k < j; ++k) {
                long long cost = dp[i][k] + dp[k][j] + (long long)i * k * j;
                if (cost < min_val) min_val = cost;
            }
            dp[i][j] = min_val;
        }
    }

    cout << dp[1][n] << '\n';

    return 0;
}
